import { useState } from 'react';
import axios from 'axios';
import toast from 'react-hot-toast';

export default function AdminCardRegister() {
  const [email, setEmail] = useState('');
  const [cardUID, setCardUID] = useState('');
  const [companyId] = useState('507f1f77bcf86cd799439011');
  const [loading, setLoading] = useState(false);

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const response = await axios.post('http://localhost:5000/api/cards/register', {
        email,
        cardUID: cardUID.trim().toUpperCase(),
        companyId
      });

      toast.success(response.data.message || 'Card successfully linked!');
      setEmail('');
      setCardUID('');
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to link card');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full max-w-md p-8 bg-white rounded-2xl shadow-lg border border-gray-100">
      <h2 className="text-2xl font-bold text-gray-900 mb-2">POS Admin Portal</h2>
      <p className="text-sm text-gray-500 mb-6">Link physical RFID tags to customer accounts.</p>

      <form onSubmit={handleRegister} className="space-y-4">
        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Customer Email</label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            placeholder="student@futa.edu.ng"
            className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Card UID (Hex)</label>
          <input
            type="text"
            value={cardUID}
            onChange={(e) => setCardUID(e.target.value)}
            required
            placeholder="e.g. 4FFE207B"
            className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 uppercase focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          className="w-full py-3 px-4 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg transition duration-200 disabled:opacity-50 shadow-sm"
        >
          {loading ? 'Linking Card...' : 'Register & Link Card'}
        </button>
      </form>
    </div>
  );
}
